package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Rejects a create-owner request that is missing or blank in any mandatory field, before the body is
 * mapped to an entity. Binds the request body (the single {@code @RequestBody} step of this pipeline)
 * and republishes it as a variable for the later steps.
 */
public class RequireOwnerFields {

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws MissingOwnerFieldsException {
        List<String> missing = new ArrayList<>();
        if (isBlank(request.getFirstName())) {
            missing.add("firstName");
        }
        if (isBlank(request.getLastName())) {
            missing.add("lastName");
        }
        if (isBlank(request.getAddress())) {
            missing.add("address");
        }
        if (isBlank(request.getCity())) {
            missing.add("city");
        }
        if (isBlank(request.getTelephone())) {
            missing.add("telephone");
        }
        if (!missing.isEmpty()) {
            throw new MissingOwnerFieldsException(missing);
        }
        validated.set(request);
    }

    private static boolean isBlank(String value) {
        return value == null || value.isBlank();
    }
}
===== NormalizeTelephone =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Normalizes a create-owner request's telephone to E.164 form: a leading {@code '+'} and country code
 * are kept when present, otherwise country code {@code '+61'} is assumed and a single leading
 * {@code '0'} is dropped from the national digits; spaces, dashes and brackets are stripped and 8 to 15
 * digits are required after the {@code '+'}. So {@code '0412 345 678'} becomes {@code '+61412345678'}.
 * The normalized value is written back onto the request (the same object the later {@link BuildOwner}
 * step maps to the entity), so it is stored and returned as {@code telephone}. A number that cannot
 * form valid E.164 is rejected via {@link InvalidTelephoneException}, which the global handler turns
 * into a 400.
 */
public class NormalizeTelephone {

    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
        request.setTelephone(TelephoneE164.normalize(request.getTelephone()));
    }
}
===== NormalizeEmail =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Normalizes an owner request's optional {@code email}. Email is optional, so an absent or blank
 * value is left untouched. When present it must be a syntactically valid address; otherwise the
 * request is rejected via {@link InvalidEmailException}, which the global handler turns into a 400.
 * A valid value is lower-cased and written back onto the request (the same object the later
 * {@link BuildOwner}/{@link ApplyOwner} step maps to the entity), so it is stored and returned
 * lower-cased as {@code email}.
 */
public class NormalizeEmail {

    /** A basic syntactic check: non-empty local part, '@', domain with at least one dot. */
    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");

    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
        String raw = request.getEmail();
        if (raw == null || raw.isBlank()) {
            return;
        }
        String email = raw.trim();
        if (!EMAIL.matcher(email).matches()) {
            throw new InvalidEmailException(raw);
        }
        request.setEmail(email.toLowerCase(Locale.ROOT));
    }
}
===== RejectDuplicateHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Rejects a create-owner request whose last name and address both match an existing owner, treating
 * two households as the same when their last name and address are equal after trimming, collapsing
 * runs of whitespace to a single space, and lower-casing. Runs before the owner is built and saved.
 * The rejection is skipped when the request sets {@code sharesHousehold} true, allowing several owners
 * to share one household. A collision is rejected via {@link DuplicateHouseholdException}, which the
 * global handler turns into a 409.
 */
public class RejectDuplicateHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String lastName = normalize(request.getLastName());
        String address = normalize(request.getAddress());
        for (Owner existing : ownerRepository.findAll()) {
            if (lastName.equals(normalize(existing.getLastName()))
                    && address.equals(normalize(existing.getAddress()))) {
                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
            }
        }
    }

    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}
