package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Rejects a create-owner request whose last name and address both match an existing owner, treating
 * two households as the same when their last name and address are equal after trimming, collapsing
 * runs of whitespace to a single space, and lower-casing. Runs before the owner is built and saved.
 * The rejection is skipped when the request sets {@code sharesHousehold} true, allowing several owners
 * to share one household. A collision is rejected via {@link DuplicateHouseholdException}, which the
 * global handler turns into a 409.
 */
public class RejectDuplicateHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String lastName = normalize(request.getLastName());
        String address = normalize(request.getAddress());
        for (Owner existing : ownerRepository.findAll()) {
            if (lastName.equals(normalize(existing.getLastName()))
                    && address.equals(normalize(existing.getAddress()))) {
                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
            }
        }
    }

    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

/**
 * Derives an owner's {@code householdId}: a stable identifier shared by every owner with the same
 * last name and address (one household). The last name and address are normalized the same way as
 * {@link RejectDuplicateHousehold} (trim, collapse runs of whitespace to a single space, lower-case)
 * before hashing, so owners created with {@code sharesHousehold} true — who by definition match an
 * existing owner's last name and address — derive the identical value. Computed as the first 12
 * upper-case hex characters of SHA-256 over the normalized pair, so it is stable across requests and
 * needs no persisted column.
 */
public final class HouseholdId {

    private HouseholdId() {
    }

    public static String of(String lastName, String address) {
        String key = normalize(lastName) + "\n" + normalize(address);
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                hex.append(String.format("%02x", b));
            }
            return hex.substring(0, 12).toUpperCase(Locale.ROOT);
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }

    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

